#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=8

REPO=$(gh repo view --json nameWithOwner --jq .nameWithOwner)

banner "Software factory setup for $REPO"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Make the repo public"
visibility=$(gh repo view "$REPO" --json visibility --jq .visibility)
if [[ "$visibility" == PUBLIC ]]; then
  say "$REPO is already public. Nothing to do."
  pause
else
  say "Branch protection and free Actions minutes need a public repo on GitHub Free."
  warn "Everything becomes visible: code, history (including commit author emails), issues and PRs."
  warn "Anything public can be cached or cloned at once, even if you switch it back."
  if confirm "Make $REPO public now?"; then
    gh repo edit "$REPO" --visibility public --accept-visibility-change-consequences
    printf '  %s✓ %s is public%s\n' "$GREEN" "$REPO" "$RESET"
  else
    SKIPPED+=("Make $REPO public: branch protection (stage 8) needs it")
  fi
  pause
fi

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Require approval for fork PR workflows"
say "Workflows on PRs from forks should wait for your approval before they run."
if gh api --method PUT "repos/$REPO/actions/permissions/fork-pr-contributor-approval" \
     -f approval_policy=all_external_contributors >/dev/null 2>&1; then
  printf '  %s✓ set%s approval for all external contributors\n' "$GREEN" "$RESET"
else
  warn "The API call failed, so set it by hand:"
  open_url "https://github.com/$REPO/settings/actions"
  step "Under 'Approval for running fork pull request workflows from contributors',"
  step "choose 'Require approval for all external contributors', then Save."
fi
pause

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Create the factory's labels"
gh label create agent-working --repo "$REPO" --force --color FBCA04 \
  --description "A factory run is working on this ticket or PR"
gh label create agent-fix-tried --repo "$REPO" --force --color C5DEF5 \
  --description "This PR had its fix run; remove to allow another"
gh label create agent-review --repo "$REPO" --force --color 1D76DB \
  --description "Owner only: start an automated review of this PR"
gh label create review-passed --repo "$REPO" --force --color 0E8A16 \
  --description "The latest automated review passed"
gh label create review-failed --repo "$REPO" --force --color D93F0B \
  --description "The latest automated review failed"
for label in ready-for-agent ready-for-human; do
  gh label list --repo "$REPO" --search "$label" --json name --jq '.[].name' | grep -qx "$label" \
    || warn "label $label is missing: the factory needs it"
done
printf '  %s✓ labels ready%s\n' "$GREEN" "$RESET"
pause

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Claude Code token"
say "Runs sign in to Claude with a long-lived token from your subscription."
step "This opens a browser sign-in, then prints the token in this terminal."
pause "Press Enter to run 'claude setup-token'"
claude setup-token
step "Copy the token it printed (starts sk-ant-oat)."
ask_secret CLAUDE_CODE_OAUTH_TOKEN "Paste the token:"
set_secret CLAUDE_CODE_OAUTH_TOKEN "$CLAUDE_CODE_OAUTH_TOKEN"
pause

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Anthropic API key for live evals"
say "Implementer runs call the API when a ticket runs its eval live."
from_envrc=""
if [[ -f .envrc ]]; then
  from_envrc=$(sed -nE "s/^export ANTHROPIC_API_KEY=[\"']?([^\"']*)[\"']?$/\1/p" .envrc | tail -n1)
fi
if [[ -n "$from_envrc" ]] && confirm "Use the ANTHROPIC_API_KEY from .envrc (…${from_envrc: -4})?"; then
  ANTHROPIC_API_KEY="$from_envrc"
else
  open_url "https://console.anthropic.com/settings/keys"
  step "Create a key (or copy an existing one)."
  ask_secret ANTHROPIC_API_KEY "Paste the API key:"
fi
set_secret ANTHROPIC_API_KEY "$ANTHROPIC_API_KEY"
pause

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "GitHub token for the factory"
say "Runs act on GitHub as you, through a token scoped to this repo only."
open_url "https://github.com/settings/personal-access-tokens/new"
step "Token name: '${REPO#*/} factory'."
step "Expiration: pick one, and put a reminder in your calendar to rotate it."
note "  When it expires every run fails; re-run this stage with the new token."
step "Repository access: 'Only select repositories' → $REPO."
step "Repository permissions: add Contents, Issues and Pull requests, and set each"
step "to 'Read and write'. They start as 'Read-only', which is not enough."
note "  Metadata (read-only) is added for you. Leave Workflows off."
step "Click 'Generate token', then copy it (starts github_pat_)."
ask_secret FACTORY_GITHUB_TOKEN "Paste the token:"
# Write access, tested by creating and deleting a throwaway label. No workflow listens for it.
if GH_TOKEN="$FACTORY_GITHUB_TOKEN" gh label create factory-token-check --repo "$REPO" --force >/dev/null 2>&1 &&
   GH_TOKEN="$FACTORY_GITHUB_TOKEN" gh label delete factory-token-check --repo "$REPO" --yes >/dev/null 2>&1; then
  printf '  %s✓ the token can write to %s%s\n' "$GREEN" "$REPO" "$RESET"
else
  warn "The token can't write to $REPO. Check its repository access, and that Contents,"
  warn "Issues and Pull requests are 'Read and write'. You can edit the token in place."
fi
set_secret FACTORY_GITHUB_TOKEN "$FACTORY_GITHUB_TOKEN"
pause

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Get the checks running on master"
say "Branch protection can only require a check GitHub has seen run on master."
step "Merge the factory PR. Its merge into master starts the 'checks' run this stage waits for."
note "  A passing run on the PR itself doesn't count: it ran on the PR's branch, not master."
while true; do
  conclusion=$(gh run list --repo "$REPO" --workflow checks.yml --branch master --limit 1 \
    --json conclusion --jq '.[0].conclusion // empty' 2>/dev/null || true)
  if [[ "$conclusion" == success ]]; then
    printf '  %s✓ checks passed on master%s\n' "$GREEN" "$RESET"
    break
  fi
  note "  No successful checks run on master yet (latest: ${conclusion:-none})."
  pause "Press Enter to check again once it has run"
done
pause

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Protect master"
say "Changes reach master only through a PR whose 'checks' job passed."
say "No approval is required (factory PRs are yours, and you can't approve your own),"
say "and the rules bind you as admin too. PRs merge by squash only."
if confirm "Apply these rules to master?"; then
  gh api --method PUT "repos/$REPO/branches/master/protection" --input - >/dev/null <<'JSON'
{
  "required_status_checks": { "strict": false, "contexts": ["checks"] },
  "enforce_admins": true,
  "required_pull_request_reviews": { "required_approving_review_count": 0 },
  "restrictions": null,
  "allow_force_pushes": false,
  "allow_deletions": false
}
JSON
  gh repo edit "$REPO" --enable-squash-merge --enable-merge-commit=false \
    --enable-rebase-merge=false --delete-branch-on-merge >/dev/null
  printf '  %s✓ master is protected%s\n' "$GREEN" "$RESET"
else
  SKIPPED+=("Branch protection on master")
fi
pause

finish
say "Try it: add 'ready-for-agent' to a ticket whose blockers are all closed."
printf '\n'
}

run_wizard "$@"; exit
